namespace LogMark.Services;

/// <summary>
/// Service for prompting user about unknown routes.
/// Core generates options from routes.md sections, UI is a dumb renderer.
/// </summary>
public interface IRoutePromptService
{
    /// <summary>
    /// Prompt user to create a new route.
    /// Returns Cancel if no handler is registered or user cancels.
    /// </summary>
    /// <param name="routeName">The route name from +notation (e.g., "acme")</param>
    /// <param name="options">Options generated by RouteService from routes.md sections</param>
    Task<RoutePromptResult> PromptForRouteCreationAsync(
        string routeName,
        RoutePromptOptions options);
}

/// <summary>
/// Options for the route creation prompt, generated from routes.md sections.
/// </summary>
/// <param name="Choices">Available route options based on sections (e.g., Project, Area)</param>
/// <param name="DefaultPath">Default path suggestion (first choice's path or route name)</param>
public record RoutePromptOptions(
    IReadOnlyList<RouteOption> Choices,
    string DefaultPath
);

/// <summary>
/// A single route option derived from a routes.md section.
/// </summary>
/// <param name="Label">Display label (e.g., "Project", "Client", "Area")</param>
/// <param name="SuggestedPath">Suggested path (e.g., "projects/acme", "clients/acme")</param>
public record RouteOption(
    string Label,
    string SuggestedPath
);

/// <summary>
/// Result from the route creation prompt.
/// </summary>
/// <param name="Outcome">What the user chose to do</param>
/// <param name="Path">The final path (potentially edited by user), null if Cancel/ReferenceOnly</param>
public record RoutePromptResult(
    RoutePromptOutcome Outcome,
    string? Path
);

/// <summary>
/// User's choice outcome from the route creation prompt.
/// </summary>
public enum RoutePromptOutcome
{
    /// <summary>Create route with the specified path</summary>
    Create,

    /// <summary>Create as reference-only (no path, no routing)</summary>
    ReferenceOnly,

    /// <summary>Don't create route, cancel the operation</summary>
    Cancel
}
